-- Brand kit > Web as the visual sitemap (canon canon-brand-kit-web-visual-sitemap; Sean, 2026-11-16: "follow the rule... and copy GeekFon's setup").
-- One entry per locked parent page, the pages that copy it as children; pictures of the live pages at 1440 px in lesaruss-hq public/branddesk/web/vegans-explore/.
update ve_brand_cartridges set data = jsonb_set(jsonb_set(data, '{web,map}', $J$[{"name": "Homepage", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/home.jpg", "href": "https://vegansexplore.com/", "what": "The front door: what Vegans Explore is, the Founding Member countdown, the video and every section.", "status": "Locked parent", "children": [{"name": "Directory", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/directory.jpg", "href": "https://vegansexplore.com/directory", "what": "The seven doors (Eat, Animals & Causes, People & Groups, Shop, Watch, Services, Travel) with Near me.", "status": "New look"}, {"name": "Search results", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/search.jpg", "href": "https://vegansexplore.com/search?q=pizza", "what": "Universal search: one box for places, people, shows and products, results as the shared Directory card.", "status": "New look"}]}, {"name": "Listing page", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/listing.jpg", "href": "https://vegansexplore.com/directory/veggie-grill", "what": "One place, person or brand: header, tabs, hours, locations, contact. Any list of listings uses the shared Directory card.", "status": "Locked parent", "children": [{"name": "Sample business", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/business-sample.jpg", "href": "https://vegansexplore.com/business/sample", "what": "Green Leaf Kitchen, the demo listing, stamped Sample.", "status": "New look"}]}, {"name": "The Welcome Guide", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/welcome-guide.jpg", "href": "https://vegansexplore.com/passport?guide=welcome", "what": "The template for every Guide: Overview, section pages, the Guide in the right rail.", "status": "Locked parent", "children": [{"name": "The Holiday Guide", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/holiday-guide.jpg", "href": "https://vegansexplore.com/guides/holiday-guide", "what": "Theo walks the holidays: ThanksLiving, menus, Give back, 11 Days of Giving.", "status": "New look"}, {"name": "The Nutrition Guide", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/nutrition-guide.jpg", "href": "https://vegansexplore.com/guides/nutrition-guide", "what": "Theo on eating Vegan and covering the basics.", "status": "New look"}, {"name": "The Vegan Dairy Guide", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/dairy-guide.jpg", "href": "https://vegansexplore.com/guides/vegan-dairy-guide", "what": "Maya on going dairy-free.", "status": "New look"}, {"name": "The Vegan Restaurant Guide", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/restaurant-guide.jpg", "href": "https://vegansexplore.com/guides/vegan-restaurant-guide", "what": "Liz walks a restaurant through its free audit.", "status": "New look"}, {"name": "For businesses", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/business-guide.jpg", "href": "https://vegansexplore.com/business-guide", "what": "Liz shows a business its page, dashboard and plan.", "status": "New look"}, {"name": "Nominate Someone", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/nominate.jpg", "href": "https://vegansexplore.com/nominate", "what": "Kai invites members to put someone forward.", "status": "New look"}]}, {"name": "Walkthrough", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/giving.jpg", "href": "https://vegansexplore.com/partners/giving", "what": "The guided white stage, every part from ve-kit.css: one slide at a time, Back, N of M, Next. First on the kit: 11 Days of Giving for brands.", "status": "Locked parent", "children": [{"name": "Partners", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/partners.jpg", "href": "https://vegansexplore.com/partners", "what": "The South Florida business walkthrough on the old dark stage. To rebuild on the Walkthrough.", "status": "Old look"}, {"name": "Sample pitch", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/pitch-sample.jpg", "href": "https://vegansexplore.com/business/pitch?c=sample", "what": "The pitch a business receives, on the old dark stage. To rebuild on the Walkthrough.", "status": "Old look"}]}, {"name": "Business dashboard", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/business-dashboard.jpg", "href": "https://vegansexplore.com/mocks/business-dashboard", "what": "The dashboard for a business, organization or creator: seven parts in one sliding row, rows with one button and a status tag.", "status": "Locked parent", "children": [{"name": "Member dashboard", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/member-dashboard.jpg", "href": "https://vegansexplore.com/dashboard", "what": "A member's own dashboard. Signed out it shows only the sign-in.", "status": "New look", "note": "Sign-in only when signed out"}]}, {"name": "Claim form", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/claim.jpg", "href": "https://vegansexplore.com/claim", "what": "A sign-up or long form: one step per view, Back, Step N of M, Next, its Guide in the Welcome Guide's rail.", "status": "Locked parent", "children": [{"name": "Your profile survey", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/survey.jpg", "href": "https://vegansexplore.com/survey", "what": "The member survey, the way in. Signed out it shows only the sign-in.", "status": "New look", "note": "Sign-in only when signed out"}]}, {"name": "City hub", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/seattle.jpg", "href": "https://vegansexplore.com/communities/seattle", "what": "A chapter: wide city art, In this community, places, events and people for one city.", "status": "Locked parent", "children": [{"name": "Los Angeles", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/los-angeles.jpg", "href": "https://vegansexplore.com/communities/los-angeles", "what": "The Los Angeles chapter.", "status": "New look"}, {"name": "Communities", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/communities.jpg", "href": "https://vegansexplore.com/communities", "what": "Every chapter, with Where should we go next.", "status": "New look"}]}, {"name": "Browse page with a banner", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/events.jpg", "href": "https://vegansexplore.com/events", "what": "A section's list under its color banner: search, Near me, filters, one row per item.", "status": "Locked parent", "children": [{"name": "Daily Pulse", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/pulse.jpg", "href": "https://vegansexplore.com/pulse", "what": "The daily briefing per city, Jobs, Classifieds, Fosters, Rescues.", "status": "New look"}, {"name": "Media", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/media.jpg", "href": "https://vegansexplore.com/media", "what": "Podcasts, shows and films, voted by the community.", "status": "New look"}, {"name": "All Guides", "img": "https://hq.lesaruss.ai/branddesk/web/vegans-explore/guides.jpg", "href": "https://vegansexplore.com/guides", "what": "Every Guide, filtered by topic.", "status": "New look"}]}]$J$::jsonb), '{web,locked}', to_jsonb('Parent pages: the template table in CLAUDE.md (locked by Sean); sitemap per canon-brand-kit-web-visual-sitemap, 16 Nov 2026'::text)), updated_at = now() where brand_slug = 'vegans-explore';
